from taf.gnb.oam.coam.cu.interfaces.cuoam24r1 import CUOAM24R1
from taf.gnb.oam.coam.cu.utilities.use_m2m_parser import enforce_use_m2m_type
from taf.gnb.oam.coam.cu.services.licensed.trs.trs_licensed_v1 import TRSLicensedv1
from taf.gnb.oam.coam.cu.schemas.licensed.cp_config.uplance_trace_stream_info_v1 import UplaneTraceStreamsInfoLICENSEDV1
from taf.gnb.oam.coam.cu.schemas.internal.asm.account_service_user_property_response_v1 import AccountServiceUserPropertys
from taf.gnb.oam.coam.cu.schemas.licensed.trs.get_ip_traffic_capture_status import IPTrafficCaptureStatus
from taf.gnb.oam.coam.cu.schemas.licensed.trs.activate_upload_operation import ActivateUploadOperation


class CUOAM24R2(CUOAM24R1):
    def __init__(self, con_details):
        super(CUOAM24R2, self).__init__(con_details)
        self.trs_licensed = TRSLicensedv1(con_details=con_details)

    @enforce_use_m2m_type
    def remove_uplane_trace_stream(self, trace_id, timeout=30, use_m2m=True):
        if use_m2m:
            self.asm_licensed.remove_uplane_trace_stream(trace_id=trace_id, timeout=timeout)
        else:
            self.asm_v1.remove_uplane_trace_stream(trace_id=trace_id, timeout=timeout)

    @enforce_use_m2m_type
    def start_uplane_trace_stream(self, trace_type, target_component, timeout=30, use_m2m=True):
        if use_m2m:
            self.asm_licensed.start_uplane_trace_stream(trace_type=trace_type,
                                                        target_component=target_component,
                                                        timeout=timeout)
        else:
            self.asm_v1.start_uplane_trace_stream(trace_type=trace_type,
                                                  target_component=target_component,
                                                  timeout=timeout)

    @enforce_use_m2m_type
    def get_active_trace_streams(self, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            res = self.asm_licensed.get_active_trace_streams(timeout=timeout)
        else:
            res = self.asm_v1.get_active_trace_streams(timeout=timeout)

        return res if raw else UplaneTraceStreamsInfoLICENSEDV1.from_object_dict(res)

    @enforce_use_m2m_type
    def stop_uplane_trace_stream(self, trace_id, timeout=30, use_m2m=True):
        if use_m2m:
            self.asm_licensed.stop_uplane_trace_stream(trace_id=trace_id, timeout=timeout)
        else:
            self.asm_v1.stop_uplane_trace_stream(trace_id=trace_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_traces_activation_status(self, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.get_traces_activation_status(timeout=timeout)
        else:
            response = self.asm_v1.get_traces_activation_status(timeout=timeout)

        return response["value"]

    def start_ip_traffic_capture(self, capture_type, measurement_point, plane_type, pod_names, timeout=30):
        return self.trs_licensed.start_ip_traffic_capture(capture_type=capture_type,
                                                          plane_type=plane_type,
                                                          pod_names=pod_names,
                                                          measurement_point=measurement_point,
                                                          timeout=timeout)

    def stop_ip_traffic_capture(self, timeout=30):
        return self.trs_licensed.stop_ip_traffic_capture(timeout=timeout)

    def abort_ip_traffic_capture(self, timeout=30):
        return self.trs_licensed.abort_ip_traffic_capture(timeout=timeout)

    def generate_ip_traffic_capture_files(self, credentials, timeout=30):
        return self.trs_licensed.generate_ip_traffic_capture_files(credentials=credentials, timeout=timeout)

    def activate_file_upload_operation(self, timeout=30, raw=False):
        response = self.trs_licensed.activate_file_upload_operation(timeout=timeout)
        return response if raw else ActivateUploadOperation.from_object_dict(response)

    def get_file_upload_operation(self, operation_id, timeout=30):
        return self.trs_licensed.get_file_upload_operation(operation_id=operation_id, timeout=timeout)

    def delete_file_upload_operation(self, timeout=30):
        return self.trs_licensed.delete_file_upload_operation(timeout=timeout)

    def upload_ip_traffic_capture_file(self, operation_id, file_name, timeout=30):
        return self.trs_licensed.upload_ip_traffic_capture_file(operation_id=operation_id,
                                                                file_name=file_name,
                                                                timeout=timeout)

    def get_ip_traffic_capture_status(self, timeout=30, raw=False):
        response = self.trs_licensed.get_ip_traffic_capture_status(timeout=timeout)
        return response if raw else IPTrafficCaptureStatus.from_object_dict(response)

    def get_account_service_user_properties(self, timeout=30, raw=False):
        response = self.asm_v1.get_account_service_user_properties(timeout=timeout)
        return response if raw else AccountServiceUserPropertys.from_object_dict(response)

    @enforce_use_m2m_type
    def reset_cells(self, dist_name, use_m2m=True, timeout=30):
        if use_m2m:
            response = self.cp_config_licensed.reset_cells(dist_name=dist_name, timeout=timeout)
        else:
            response = self.cp_config.reset_cells(dist_name=dist_name, timeout=timeout)

        return response

    def get_counter_objects(self, counter_id, timeout=30):
        return self.pm_v2.get_counter_objects(counter_id=counter_id, timeout=timeout)
